mapper.select:
SELECT id, store_id, zookie, operation, object_type, object_id, relation,
       subject_type, subject_id, subject_relation, operation_time, operator_id, trace_id,
       tenant_id, create_time, created_by, update_time, updated_by, is_deleted
FROM fga_changelog
WHERE store_id = #{storeId}
  AND zookie > #{startZookie}

      AND zookie <= #{endZookie}

  AND is_deleted = 0
ORDER BY zookie ASC

    LIMIT #{limit}

SELECT id, store_id, zookie, operation, object_type, object_id, relation,
       subject_type, subject_id, subject_relation, operation_time, operator_id, trace_id,
       tenant_id, create_time, created_by, update_time, updated_by, is_deleted
FROM fga_changelog
WHERE store_id = #{storeId}
  AND zookie > #{afterZookie}
  AND is_deleted = 0
ORDER BY zookie ASC

    LIMIT #{limit}

mapper.delete:
DELETE FROM fga_changelog
WHERE store_id = #{storeId}
  AND zookie < #{beforeZookie}
